+const form = document.getElementById('contactForm');
+const fullNameInput = document.getElementById('fullName');
+const emailInput = document.getElementById('email');
+const phoneInput = document.getElementById('phone');
+const successMessage = document.getElementById('successMessage');
+
+const validationRules = {
+    fullName: {
+        validate: (value) => value.trim().length > 0,
+        message: 'Full name is required'
+    },
+    email: {
+        validate: (value) => {
+            const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
+            return value.trim().length > 0 && emailRegex.test(value);
+        },
+        message: 'Please enter a valid email address'
+    },
+    phone: {
+        validate: (value) => {
+            if (value.trim().length === 0) return true;
+            const phoneRegex = /^(\+?1[-.\s]?)?\(?[0-9]{3}\)?[-.\s]?[0-9]{3}[-.\s]?[0-9]{4}$/;
+            return phoneRegex.test(value);
+        },
+        message: 'Please enter a valid phone number'
+    }
+};
+
+function getErrorElement(inputId) {
+    return document.querySelector(`#${inputId}`).parentElement.querySelector('.error-message');
+}
+
+function showError(inputId, message) {
+    const errorElement = getErrorElement(inputId);
+    errorElement.textContent = message;
+}
+
+function clearError(inputId) {
+    const errorElement = getErrorElement(inputId);
+    errorElement.textContent = '';
+}
+
+function validateField(inputId) {
+    const input = document.getElementById(inputId);
+    const value = input.value;
+    const rule = validationRules[inputId];
+
+    if (!rule.validate(value)) {
+        showError(inputId, rule.message);
+        return false;
+    } else {
+        clearError(inputId);
+        return true;
+    }
+}
+
+function validateForm() {
+    let isValid = true;
+    isValid = validateField('fullName') && isValid;
+    isValid = validateField('email') && isValid;
+    isValid = validateField('phone') && isValid;
+    return isValid;
+}
+
+function resetForm() {
+    form.reset();
+    clearError('fullName');
+    clearError('email');
+    clearError('phone');
+    successMessage.classList.add('hidden');
+}
+
+// Attach blur event listeners for validation
+fullNameInput.addEventListener('blur', () => validateField('fullName'));
+emailInput.addEventListener('blur', () => validateField('email'));
+phoneInput.addEventListener('blur', () => validateField('phone'));
+
+// Handle form submission
+form.addEventListener('submit', (e) => {
+    e.preventDefault();
+
+    if (validateForm()) {
+        successMessage.classList.remove('hidden');
+        form.style.display = 'none';
+
+        setTimeout(() => {
+            resetForm();
+            form.style.display = 'flex';
+        }, 3000);
+    }
+});
+
